begin;
select plan(22);
select has_table('public','medication_treatments','stable treatment table');
select has_table('public','medication_treatment_revisions','immutable schedule revisions');
select has_table('public','medication_applications','application identities');
select has_table('public','medication_application_events','private audit events');
select has_table('private','medication_operations','separate operation receipts');
insert into auth.users(id) values ('57000000-0000-4000-8000-000000000001'),('57000000-0000-4000-8000-000000000002');
insert into auth.sessions(id,user_id,not_after) values ('67000000-0000-4000-8000-000000000001','57000000-0000-4000-8000-000000000001',now()+interval '1 hour'),('67000000-0000-4000-8000-000000000002','57000000-0000-4000-8000-000000000002',now()+interval '1 hour');
insert into public.staff_members(user_id,active,display_name) values ('57000000-0000-4000-8000-000000000001',true,'Equipe de teste A');
insert into public.animals(id,name,species,sex,size,approximate_age,is_published) values ('77000000-0000-4000-8000-000000000001','Fixture agenda','dog','female','small','2 anos',true);
insert into public.medication_treatments(id,animal_id,created_by,updated_by) values ('87000000-0000-4000-8000-000000000001','77000000-0000-4000-8000-000000000001','57000000-0000-4000-8000-000000000001','57000000-0000-4000-8000-000000000001');
insert into public.medication_treatment_revisions(treatment_id,revision,medication_name,schedule_mode,starts_at,ends_at,fixed_times,created_by) values ('87000000-0000-4000-8000-000000000001',1,'Medicação de teste','fixed_times','2026-11-01T11:00:00Z','2026-11-02T23:00:00Z',array['08:00','20:00'],'57000000-0000-4000-8000-000000000001');
insert into public.medication_applications(id,treatment_id,revision,scheduled_at) values ('97000000-0000-4000-8000-000000000001','87000000-0000-4000-8000-000000000001',1,'2026-11-01T11:00:00Z');
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select throws_ok($$select * from public.medication_treatments$$,'42501',null,'anonymous treatment access denied even for published animal');
select throws_ok($$select * from public.medication_application_events$$,'42501',null,'anonymous audit denied');
reset role;
select set_config('request.jwt.claims','{"sub":"57000000-0000-4000-8000-000000000002","session_id":"67000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.medication_treatments),0,'non staff cannot read treatments');
select is((select count(*)::int from public.medication_applications),0,'non staff cannot read applications');
reset role;
select set_config('request.jwt.claims','{"sub":"57000000-0000-4000-8000-000000000001","session_id":"67000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.medication_treatments where id='87000000-0000-4000-8000-000000000001'),1,'current staff can read treatment');
select is((select count(*)::int from public.medication_treatment_revisions where treatment_id='87000000-0000-4000-8000-000000000001'),1,'current staff can read revision');
select is((select count(*)::int from public.medication_applications where id='97000000-0000-4000-8000-000000000001'),1,'current staff can read application');
select throws_ok($$select * from public.medication_application_events$$,'42501',null,'audit available only by narrow RPC');
select throws_ok($$select * from private.medication_operations$$,'42501',null,'receipts are not directly readable');
select throws_ok($$update public.medication_treatments set status='stopped'$$,'42501',null,'direct writes denied');
reset role;
select throws_ok($$delete from public.animals where id='77000000-0000-4000-8000-000000000001'$$,'23503',null,'animal deletion cannot cascade away medication history');
select throws_ok($$insert into public.medication_applications(treatment_id,revision,scheduled_at) values ('87000000-0000-4000-8000-000000000001',1,'2026-11-01T11:00:00Z')$$,'23505',null,'same treatment and instant cannot duplicate an active application');
select ok((select agenda_version>=0 from private.medication_agenda_state),'transactional agenda counter remains nonnegative with existing local data');
select set_config('request.jwt.claims','{"sub":"57000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.medication_treatments),0,'missing auth session blocks read');
reset role;
select set_config('request.jwt.claims','{"sub":"57000000-0000-4000-8000-000000000001","session_id":"67000000-0000-4000-8000-000000000001","role":"authenticated","exp":1}',true);
set local role authenticated;
select is((select count(*)::int from public.medication_treatments),0,'expired token blocks read');
reset role;
update auth.sessions set not_after=now()-interval '1 minute' where id='67000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"sub":"57000000-0000-4000-8000-000000000001","session_id":"67000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.medication_applications),0,'expired server session blocks read');
reset role;
update auth.sessions set not_after=now()+interval '1 hour' where id='67000000-0000-4000-8000-000000000001';
update public.staff_members set active=false where user_id='57000000-0000-4000-8000-000000000001';
set local role authenticated;
select is((select count(*)::int from public.medication_treatments),0,'revoked staff blocks read');
select * from finish();
rollback;
